export function reforecastPublicationState(record,publications=[]){
 const head=record?.head||{},revisionId=record?.revision?.revision_id||head.revision_id;
 const matches=publications.filter(row=>row.communityId===head.community_id&&row.scenarioId===headId(record||{})&&row.revisionId===revisionId);
 const activePeriods=[...new Set(matches.flatMap(row=>row.activePeriods||[]))].sort();
 return {status:activePeriods.length?'published':head.status||'working_draft',label:activePeriods.length?'Published / Active':matches.length?'Published / Superseded':label(head.status),activePeriods,publicationIds:matches.map(row=>row.publicationId)};
}
function statusOf(s){return reforecastPublicationState(s.record,s.active).status;}
function stateLabel(s){return reforecastPublicationState(s.record,s.active).label;}
export function reforecastReportPeriods(snapshot,from='',to=''){
 const all=[...new Set(snapshot?.identity?.periods||snapshot?.periods||[])].sort();
 if((from&&!/^20\d{2}-(0[1-9]|1[0-2])$/.test(from))||(to&&!/^20\d{2}-(0[1-9]|1[0-2])$/.test(to)))throw Error('Choose valid reporting months.');
 if(from&&to&&from>to)throw Error('The report start month must be on or before its end month.');
 const periods=all.filter(period=>(!from||period>=from)&&(!to||period<=to));
 if(!periods.length)throw Error('No months from this saved snapshot fall within the selected range.');
 return periods;
}
export function reforecastMonthEvidence({communityId,period,source,entries=[],publications=[],uploads=[],sourceError,uploadError}){
 if(source?.actuals?.notApplicablePeriods?.includes(period))return {status:'Not applicable',explanation:'Before this property’s first expected financial month.'};
 const close=source?.actuals?.closeVersions?.find(row=>row.period===period);
 if(close)return {status:'Closed',explanation:'Governed actuals are locked. Close '+close.versionId};
 const active=publications.find(row=>row.communityId===communityId&&(row.activePeriods||[]).includes(period));
 if(active)return {status:'Published / Active',explanation:'Active publication '+active.publicationId+'; open forecast remains distinct from actuals.'};
 const covering=entries.filter(row=>row.head?.community_id===communityId&&row.revision?.payload?.periods?.includes(period));
 covering.sort((a,b)=>String(b.revision?.created_at||b.head?.updated_at||'').localeCompare(String(a.revision?.created_at||a.head?.updated_at||''))||Number(b.head?.revision||0)-Number(a.head?.revision||0));
 const latest=covering[0];
 if(latest){
  const issues=(latest.snapshot?.diagnostics||[]).filter(row=>['error','blocking'].includes(row.severity)&&(!row.period||row.period===period));
  const state=reforecastPublicationState(latest,publications),name=latest.revision.payload.name||'Reforecast';
  return {status:issues.length?'Blocked · '+state.label:state.label,explanation:name+' · revision '+latest.head.revision+(issues.length?': '+issues.slice(0,3).map(row=>row.message).join('; '):'. '+(state.status==='locked'?'Locked revision awaits explicit publication.':'Saved workflow state; no active designation.'))};
 }
 const evidence=uploads.filter(row=>row.community_id===communityId&&(Array.isArray(row.periods)?row.periods:[]).includes(period));
 if(evidence.length)return {status:'Uploaded · Mapping Required',explanation:evidence.length+' immutable workbook import(s) contain this month. No shared reforecast revision links reviewed values yet; resume the saved import.'};
 if(sourceError)return {status:'Unavailable',explanation:'Canonical evidence could not be read: '+sourceError};
 if(!source)return {status:'Unavailable',explanation:'Canonical month evidence has not been loaded.'};
 if(source.actuals?.cutoffPeriod&&period<=source.actuals.cutoffPeriod)return {status:'Blocked',explanation:'No governed close exists for this expected month at or before the actual cutoff. Reconcile and publish its financial package.'};
 if(uploadError)return {status:'Unavailable',explanation:'No governed close or shared reforecast is recorded; saved workbook metadata could not be read: '+uploadError};
 const hasBudget=source.baseline?.lines?.some(row=>row.period===period);
 return {status:'Blocked',explanation:hasBudget?'Original budget is available. Create or import a working reforecast, review it, then publish the locked revision.':'No governed close, original budget coverage, or shared reforecast is recorded for this month.'};
}
export async function readReforecastApprovalEvidence(central,{communityIds,year}){
 const actor=central.getSession()?.user?.id,periods=periodsFor(year),sources={},sourceErrors={},uploads=[];
 const guard=()=>{if(actor!==central.getSession()?.user?.id)throw Error('The signed-in account changed while reading the approval center.');};
 if(!communityIds.length)return {entries:[],active:[],sources,sourceErrors,uploads};
 const [entries,active]=await Promise.all([store.readWorkspace(central,{communityIds}),store.readActive(central,{communityIds,periods})]);guard();
 for(let i=0;i<communityIds.length;i+=4){const ids=communityIds.slice(i,i+4),results=await Promise.allSettled(ids.map(communityId=>store.readSourceBundle(central,{communityId,periods})));guard();results.forEach((result,index)=>{if(result.status==='fulfilled')sources[ids[index]]=result.value;else sourceErrors[ids[index]]=result.reason.message;});}
 let uploadError='';
 try{for(let offset=0;;offset+=100){const page=await central.fetchJson(`/atlas_reforecast_uploads?community_id=in.(${communityIds.join(',')})&select=upload_id,community_id,created_at,periods:payload->summary->periods&order=created_at.desc,upload_id.desc&limit=100&offset=${offset}`);guard();if(!Array.isArray(page)||page.some(row=>!communityIds.includes(row.community_id)))throw Error('Saved import metadata scope mismatch.');uploads.push(...page);if(page.length<100)break;}}
 catch(error){guard();uploadError=error.message;}
 return {entries,active,sources,sourceErrors,uploads,uploadError};
}
export function cacheReforecastSource(R,source,year){
 if(!R||!source?.communityId)return;R.reforecastSources||={};R.reforecastSources[source.communityId+'|'+year]=source;
 for(const property of R.app?.state?.properties||[]){if(property.id===source.communityId||property.communityId===source.communityId||property.community_id===source.communityId||R.reforecastPropertyAssignments?.[property.id]===source.communityId)R.reforecastSources[property.id+'|'+year]=source;}
}
async function loadApprovals(s){
 safeActor(s);const epoch=++s.approvalEpoch;s.loading=true;s.error='';render(s);
 try{const result=await readReforecastApprovalEvidence(s.central,{communityIds:s.communities.map(row=>row.community_id),year:s.approvalYear||s.year});if(epoch!==s.approvalEpoch)return;safeActor(s);s.approvalEvidence=result;for(const source of Object.values(result.sources))cacheReforecastSource(s.R,source,s.approvalYear||s.year);}
 catch(error){s.error=error.message;}finally{if(epoch===s.approvalEpoch){s.loading=false;render(s);}}
}
function editable(s){return !['submitted','approved','locked','published'].includes(statusOf(s));}
function eventMeta(s){return {actor:s.actor,timestamp:new Date().toISOString(),versionId:uuid(),driverVersion:uuid()};}
function mark(s){if(s.edit)s.edit.driverVersion=fingerprint({drivers:s.edit.drivers||[],overrides:s.edit.overrides||[]});s.dirty=true;s.pendingRequest=null;s.preview=null;s.error='';}
function preview(s){if(!s.source||!s.edit)return null;try{return computeReforecast({...s.source,scenario:{...s.edit,versionId:s.record?.revision?.revision_id||s.edit.versionId||'unsaved',driverVersion:fingerprint({drivers:s.edit.drivers,overrides:s.edit.overrides})}});}catch(e){s.previewError=e.message;return null;}}
export function reforecastSourceChanged(s){const retained=s.record?.revision?.source?.sourceVersion||s.record?.snapshot?.identity?.sourceVersion;return Boolean(retained&&s.source?.sourceVersion&&retained!==s.source.sourceVersion);}
export function reforecastCurrentSnapshot(s){if(!editable(s)&&s.record?.snapshot)return s.record.snapshot;if(s.dirty||!s.record?.snapshot||reforecastSourceChanged(s))return s.preview||(s.preview=preview(s));return s.record.snapshot;}
