 try{const [entries,source,active,history]=await Promise.all([store.readWorkspace(s.central,{communityIds:[s.cid]}),store.readSourceBundle(s.central,{communityId:s.cid,periods:periodsFor(s.year)}),store.readActive(s.central,{communityIds:[s.cid],periods:periodsFor(s.year)}),store.readPublicationHistory(s.central,{communityId:s.cid}).then(rows=>({rows}),error=>({error:error.message}))]);if(epoch!==s.epoch)return;safeActor(s);s.entries=entries;s.source=source;cacheReforecastSource(s.R,source,s.year);s.active=active;s.publicationHistory=history.rows||[];s.publicationHistoryError=history.error||'';s.record=null;s.edit=null;s.dirty=false;s.preview=null;}
