 const requestBody={communityId:s.cid,scenarioId:headId(s.record||{})||s.scenarioId,expectedRevision:s.record?.head?.revision||0,action:kind,payload:clone(s.edit)};
 const requestKey=JSON.stringify(requestBody);if(s.pendingRequest?.key!==requestKey)s.pendingRequest={key:requestKey,id:uuid()};render(s);
