 c.querySelector('[data-scenario]')?.addEventListener('change',e=>{if(s.dirty){s.error='Save the current working draft before opening another.';render(s);}else selectScenario(s,e.target.value);});
 c.querySelector('[data-cell-reason]')?.addEventListener('input',e=>{s.cellReason=e.target.value;if(s.cellReason.trim().length>=3)for(const [key,raw] of Object.entries(s.pendingCells||{})){const [period,code]=JSON.parse(key);updateReforecastCell(s,period,code,raw);delete s.pendingCells[key];}});
 c.querySelector('[data-cell-reason]')?.addEventListener('change',()=>render(s));
 for(const selector of ['[data-calendar]','[data-start-month]','[data-calendar-confirm]'])c.querySelector(selector)?.addEventListener('change',()=>{s.edit.calendar={basis:c.querySelector('[data-calendar]').value,startMonth:Number(c.querySelector('[data-start-month]').value),confirmed:c.querySelector('[data-calendar-confirm]').checked,periods:[...s.edit.periods],scenario:s.edit.name,reviewedBy:s.actor,reviewedAt:new Date().toISOString()};s.edit.governanceSchemaVersion=2;mark(s);});
 c.querySelectorAll('[data-edit]').forEach(el=>el.oninput=()=>{s.edit[el.dataset.edit]=el.value||null;mark(s);});
