export function reforecastDraftFromLegacy({input,scenario,source,actor,propertyId,reason,timestamp=new Date().toISOString()}){
 if(!source?.communityId||input.communityId!==source.communityId)throw Error('Confirm the browser property corresponds to the selected canonical property.');
 if(!actor||!reason?.trim())throw Error('A signed-in user and copy reason are required.');
 const periods=[...source.periods],open=new Set(periods.filter(period=>!source.actuals?.cutoffPeriod||period>source.actuals.cutoffPeriod));
 const drivers=clone(input.scenario?.drivers||[]).map(driver=>({...driver,periods:(driver.periods||periods).filter(period=>open.has(period))})).filter(driver=>driver.periods.length);
 const overrides=clone(input.scenario?.overrides||[]).filter(row=>open.has(row.period)).map(row=>({period:row.period,accountCode:row.accountCode,amount:row.amount,reason:reason.trim(),confirmed:true,ownerId:actor,effectivePeriod:row.period,reviewedAt:timestamp,before:null,after:row.amount,source:{kind:'explicit_browser_scenario_copy',propertyId,scenarioId:scenario.id}}));
 return {governanceSchemaVersion:2,calendar:null,name:(scenario.name||'Browser scenario')+' Reforecast',model:scenario.model||'conventional',periods,baselineVersionIds:source.baseline?.versionIds||[],registryVersionId:source.registry?.version||null,uploadId:null,ownerId:actor,reviewerId:null,drivers,overrides,suggestionDecisions:[],reason:reason.trim(),history:[{action:'copy_browser_scenario',actor,timestamp,sourcePropertyId:propertyId,sourceScenarioId:scenario.id,sourceScenarioName:scenario.name,reason:reason.trim(),before:null,after:{drivers:clone(drivers),overrides:clone(overrides)}}]};
}
