async function applyWorkbookImport(s,result){
 safeActor(s);
 const sameCommunity=s.cid===result.communityId;
 if(s.dirty&&!sameCommunity)throw Error('Save the current working draft before switching properties. The imported workbook is already saved and can be resumed.');
 const module=await import('./reforecast-import-ui.mjs?v=9de482916e47adf1');
 if(!sameCommunity){s.cid=result.communityId;await loadCommunity(s);if(s.error)throw Error(s.error);}
 if(!s.edit||!editable(s)){
  if(result.source)s.source=result.source;
  newScenario(s,result.mapping?.periods?.length?result.mapping.periods:result.source?.periods||periodsFor(s.year));
  s.edit.name=(result.upload.payload?.source?.fileName||'Imported workbook').replace(/\.xlsx$/i,'')+' Reforecast';
 }
 const next=module.mergeReforecastImportIntoDraft(s.edit,result,{actor:s.actor});
 const source=await store.readSourceBundle(s.central,{communityId:s.cid,periods:next.periods,baselineVersionIds:next.baselineVersionIds,registryVersionId:next.registryVersionId});safeActor(s);
 s.source=source;s.edit=next;mark(s);
 s.message=result.ready?`Workbook evidence is saved. ${result.lines.length} reviewed values are in the working draft. Choose Save Working Draft to persist those changes.`:'Workbook evidence is saved and linked to this working draft. Mapping remains required; no imported values were applied. Choose Save Working Draft to persist the link.';
 render(s);
}
